      "mainEntity": [
        {
          "@type": "Question",
          "name": "How can a plumbing leak be distinguished from failed shower waterproofing?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The source needs investigation. Supply and waste pipe tests, the pattern of water during use and access findings can help separate causes. Dampness alone cannot confirm a failed membrane or a leaking pipe."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need a plumber or a waterproofing specialist for a leaking shower?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Start by describing the symptoms. We assess the plumbing and explain if the findings point to waterproofing or other building work outside the agreed plumbing scope. These are different repairs and should not be assumed to share one quote."
          }
        },
        {
          "@type": "Question",
          "name": "Can you guarantee the shower can be repaired without removing tiles?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Access depends on the fault and the installation. We explain the proposed access and the repair scope before work proceeds, including who handles any affected finishes."
          }
        },
        {
          "@type": "Question",
          "name": "What should I send before a shower leak visit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Provide the suburb, where water appears, when it happens and the affected room below or beside the shower. Safely taken photos are optional; do not enter a wet electrical area or open walls to gather evidence."
          }
        }
      ]
    }
